const inquiries = $('Get Inquiries').all().filter(r => r.json.inquiry_id);
const assignments = $('Get Assignments').all().filter(r => r.json.assignment_id);
const feedback = $('Get Feedback').all().filter(r => r.json.feedback_id);
const doctors = $('Get Doctors').all().filter(r => r.json.doctor_id);

// Период — последние 7 дней
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const weekAgoStr = weekAgo.toISOString().slice(0, 10);

const recentInquiries = inquiries.filter(r => r.json.date >= weekAgoStr);
const allInquiries = inquiries;

// Обращения по направлениям (за неделю)
const byDirection = {};
recentInquiries.forEach(r => {
  const dir = r.json.direction || 'unknown';
  byDirection[dir] = (byDirection[dir] || 0) + 1;
});

// Обращения по срочности (за неделю)
const byUrgency = {};
recentInquiries.forEach(r => {
  const urg = r.json.urgency || 'unknown';
  byUrgency[urg] = (byUrgency[urg] || 0) + 1;
});

// Статусы обращений (за неделю)
const byStatus = {};
recentInquiries.forEach(r => {
  const st = r.json.status || 'unknown';
  byStatus[st] = (byStatus[st] || 0) + 1;
});

// Загрузка врачей
const doctorLoad = doctors.map(r => ({
  name: r.json.name,
  active: parseInt(r.json.active_patients) || 0,
  max: parseInt(r.json.max_patients) || 0,
  load_pct: Math.round(((parseInt(r.json.active_patients) || 0) / (parseInt(r.json.max_patients) || 1)) * 100)
}));

// Средний рейтинг из фидбэка (за неделю)
const recentFeedback = feedback.filter(r => r.json.received_at >= weekAgoStr);
let avgScore = 0;
if (recentFeedback.length > 0) {
  const total = recentFeedback.reduce((sum, r) => sum + (parseInt(r.json.score) || 0), 0);
  avgScore = (total / recentFeedback.length).toFixed(1);
}

// Использование голоса/фото
const voiceCount = recentInquiries.filter(r => r.json.voice_used === 'TRUE').length;
const photoCount = recentInquiries.filter(r => r.json.photo_analysis && r.json.photo_analysis !== '').length;

// Мультиязычность
const byLanguage = {};
recentInquiries.forEach(r => {
  const lang = r.json.language || 'unknown';
  byLanguage[lang] = (byLanguage[lang] || 0) + 1;
});

const analyticsData = {
  period: `${weekAgoStr} — ${now.toISOString().slice(0, 10)}`,
  total_all_time: allInquiries.length,
  total_week: recentInquiries.length,
  by_direction: JSON.stringify(byDirection),
  by_urgency: JSON.stringify(byUrgency),
  by_status: JSON.stringify(byStatus),
  by_language: JSON.stringify(byLanguage),
  doctor_load: JSON.stringify(doctorLoad),
  avg_feedback_score: avgScore,
  feedback_count: recentFeedback.length,
  voice_used: voiceCount,
  photo_used: photoCount
};

return analyticsData;

const data = $json;

const systemPrompt = `Ты — аналитик клиники «НоваМед». На основе данных за неделю сформируй краткий аналитический отчёт для администратора клиники.

Пиши на русском. Формат: структурированный текст с эмодзи для наглядности. Не более 15 предложений. В конце — 2-3 конкретные рекомендации.

ДАННЫЕ ЗА ПЕРИОД ${data.period}:

Всего обращений за неделю: ${data.total_week}
Всего обращений за всё время: ${data.total_all_time}

По направлениям: ${data.by_direction}
По срочности: ${data.by_urgency}
По статусам: ${data.by_status}
По языкам: ${data.by_language}

Загрузка врачей: ${data.doctor_load}

Средний рейтинг обратной связи: ${data.avg_feedback_score} (из ${data.feedback_count} отзывов)

Голосовых обращений: ${data.voice_used}
Фото-обращений: ${data.photo_used}

