const requestBody = {
  model: 'deepseek-v4-flash',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: 'Сформируй еженедельный отчёт.' }
  ],
  temperature: 0.4
};

return {
  request_body: JSON.stringify(requestBody)
};

